def test_macro_with_varargs():
    """Test a macro with variable arguments."""
    env = Environment()
    # Create a macro manually to test varargs functionality
    def list_items_func(*items):
        return ", ".join(items)

    macro = Macro(env, list_items_func, "list_items", ["items"], False, True, False)
    result = macro("apple", "banana", "cherry")
    assert result == "apple, banana, cherry"
    print("✓ Macro with varargs test passed")

def test_macro_with_kwargs():
    """Test a macro with keyword arguments."""
    env = Environment()
    # Create a macro manually to test kwargs functionality
    def format_person_func(**kwargs):
        return ", ".join(f"{key}: {value}" for key, value in kwargs.items())

    macro = Macro(env, format_person_func, "format_person", [], True, False, False)
    result = macro(name="John", age="30")
    assert result == "name: John, age: 30"
    print("✓ Macro with kwargs test passed")

